// src/api/SettingApi.js
import { get, post, put, del } from './HttpClient';

// ===== folders =====
export function fetchWatchedFolders() {
  return get('/settings/folders');
}
export function addWatchedFolder({ name, path }) {
  return post('/settings/folders', { name, path });
}
export function deleteWatchedFolder(id) {
  return del(`/settings/folders/${id}`);
}

// ===== exceptions =====
export function fetchExceptionRules() {
  return get('/settings/exceptions');
}
export function addExceptionRule({ type, pattern, memo }) {
  return post('/settings/exceptions', { type, pattern, memo });
}
export function deleteExceptionRule(id) {
  return del(`/settings/exceptions/${id}`);
}

// ===== (향후) notification settings =====
// (백엔드 아직 없으면 404 날 수 있음 → 페이지에서 catch 처리)
export function fetchNotificationSettings() {
  return get('/settings/notification');
}
export function updateNotificationSettings({ popup, sound, tray }) {
  return put('/settings/notification', { popup, sound, tray });
}

// ===== (향후) reset/update/feedback =====
export function resetSettings() {
  return post('/settings/reset');
}
export function fetchAppVersion() {
  return get('/app/version');
}
export function checkAppUpdate() {
  return get('/app/update/check');
}
export function sendFeedback({ name, email, content }) {
  return post('/support/feedback', { name, email, content });
}
